  2788  {
  2789          struct sc_pkcs11_card *p11card = slot->p11card;
  2790          struct pkcs15_fw_data *fw_data = NULL;
  2791          struct sc_pkcs15init_certargs args;
  2792          struct pkcs15_any_object *cert_any_obj = NULL;
  2793          struct sc_pkcs15_object *cert_obj = NULL;
  2794          CK_CERTIFICATE_TYPE     cert_type;
  2795          CK_BBOOL                bValue;
  2796          int                     rc;
  2797          CK_RV rv;
  2798          char label[SC_PKCS15_MAX_LABEL_SIZE];
  2799
  2800          memset(&args, 0, sizeof(args));
  2801          if (!p11card)
  2802                  return sc_to_cryptoki_error(SC_ERROR_INVALID_CARD, "C_CreateObject");
  2803          fw_data = (struct pkcs15_fw_data *) p11card->fws_data[slot->fw_data_idx];
  2804          if (!fw_data)
  2805                  return sc_to_cryptoki_error(SC_ERROR_INTERNAL, "C_CreateObject");
  2806          if (!fw_data->p15_card)
  2807                  return sc_to_cryptoki_error(SC_ERROR_INVALID_CARD, "C_CreateObject");
  2808
  2809          /* Get the key type */
  2810          rv = attr_find(pTemplate, ulCount, CKA_CERTIFICATE_TYPE,
  2811                                  &cert_type, NULL);
  2812          if (rv != CKR_OK)
  2813                  return rv;
  2814          if (cert_type != CKC_X_509)
  2815                  return CKR_ATTRIBUTE_VALUE_INVALID;
  2816
  2817          while (ulCount--) {
  2818                  CK_ATTRIBUTE_PTR attr = pTemplate++;
  2819
  2820                  switch (attr->type) {
  2821                  /* Skip attrs we already know or don't care for */
  2822                  case CKA_CLASS:
  2823                          break;
  2824                  case CKA_PRIVATE:
  2825                          attr_extract(attr, &bValue, NULL);
  2826                          if (bValue) {
  2827                                  rv = CKR_TEMPLATE_INCONSISTENT;
  2828                                  goto out;
  2829                          }
  2830                          break;
  2831                  case CKA_LABEL:
  2832                          args.label = set_cka_label(attr, label);
  2833                          break;
  2834                  case CKA_ID:
  2835                          args.id.len = sizeof(args.id.value);
  2836                          rv = attr_extract(attr, args.id.value, &args.id.len);
  2837                          if (rv != CKR_OK)
  2838                                  goto out;
  2839                          break;
  2840                  case CKA_VALUE:
  2841                          args.der_encoded.len = attr->ulValueLen;
  2842                          args.der_encoded.value = (u8 *) attr->pValue;
  2843                          break;
  2844                  default:
  2845                          /* ignore unknown attrs, or flag error? */
  2846                          continue;
  2847                  }
  2848          }
  2849
  2850          if (args.der_encoded.len == 0) {
  2851                  rv = CKR_TEMPLATE_INCOMPLETE;
  2852                  goto out;
  2853          }
  2854
  2855          rc = sc_pkcs15init_store_certificate(fw_data->p15_card, profile, &args, &cert_obj);
  2856          if (rc < 0) {
  2857                  rv = sc_to_cryptoki_error(rc, "C_CreateObject");
  2858                  goto out;
  2859          }
  2860          /* Create a new pkcs11 object for it */
  2861          __pkcs15_create_cert_object(fw_data, cert_obj, &cert_any_obj);
  2862          pkcs15_add_object(slot, cert_any_obj, phObject);
  2863
  2864          rv = CKR_OK;
  2865
  2866  out:    return rv;
  2867  }
