  2986                   * so only enforce for secret_key
  2987                   */
  2988                  if (_class != CKO_SECRET_KEY)
  2989                          _token = TRUE; /* default if not in template */
  2990          }
  2991          else if (rv != CKR_OK) {
  2992                  return rv;
  2993          }
  2994
  2995          /* TODO The previous code does not check for CKA_TOKEN=TRUE
  2996           * PKCS#11 CreatObject examples always have it, but
  2997           * PKCS#11 says the default is false.
  2998           * for backward compatibility, will default to TRUE
  2999           */
  3000           /* Dont need profile id creating session only objects,
  3001                  except when the card supports temporary on card session objects */
  3002          p15init_create_object = _token == TRUE || (p11card->card->caps & SC_CARD_CAP_ONCARD_SESSION_OBJECTS) == SC_CARD_CAP_ONCARD_SESSION_OBJECTS;
  3003
  3004          if (p15init_create_object) {
  3005                  struct sc_aid *aid = NULL;
  3006
  3007                  rc = sc_lock(p11card->card);
  3008                  if (rc < 0)
  3009                          return sc_to_cryptoki_error(rc, "C_CreateObject");
  3010
  3011                  /* Bind the profile */
  3012                  rc = sc_pkcs15init_bind(p11card->card, "pkcs15", NULL, slot->app_info, &profile);
  3013                  if (rc < 0) {
  3014                          sc_unlock(p11card->card);
  3015                          return sc_to_cryptoki_error(rc, "C_CreateObject");
  3016                  }
  3017
  3018                  if (slot->app_info)
  3019                          aid = &slot->app_info->aid;
  3020
  3021                  rc = sc_pkcs15init_finalize_profile(p11card->card, profile, aid);
  3022                  if (rc != CKR_OK) {
  3023                          sc_log(context, "Cannot finalize profile: %i", rc);
  3024                          sc_unlock(p11card->card);
  3025                          return sc_to_cryptoki_error(rc, "C_CreateObject");
  3026                  }
  3027
  3028                  sc_pkcs15init_set_p15card(profile, fw_data->p15_card);
  3029          }
  3030          switch (_class) {
  3031          case CKO_PRIVATE_KEY:
  3032                  rv = pkcs15_create_private_key(slot, profile, pTemplate, ulCount, phObject);
  3033                  break;
  3034          case CKO_PUBLIC_KEY:
  3035                  rv = pkcs15_create_public_key(slot, profile, pTemplate, ulCount, phObject);
  3036                  break;
  3037          case CKO_CERTIFICATE:
  3038                  rv = pkcs15_create_certificate(slot, profile, pTemplate, ulCount, phObject);
  3039                  break;
  3040          case CKO_DATA:
  3041                  rv = pkcs15_create_data(slot, profile, pTemplate, ulCount, phObject);
  3042                  break;
  3043          case CKO_SECRET_KEY:
  3044                  rv = pkcs15_create_secret_key(slot, profile, pTemplate, ulCount, phObject);
  3045                  break;
  3046          default:
  3047                  rv = CKR_FUNCTION_NOT_SUPPORTED;
  3048          }
  3049
  3050          if (p15init_create_object) {
  3051                  // TODO: after sc_pkcs15init_unbind, user may have to enter PIN on a pin pad reader even though authentication state
  3052                  // is supposed to remain open. Check why this happens.
  3053                  sc_pkcs15init_unbind(profile);
  3054                  sc_unlock(p11card->card);
  3055          }
  3056
  3057          return rv;
  3058  }
